import{_ as a,o as s,c as t,a6 as n}from"./chunks/framework.BJFjZBwW.js";const h=JSON.parse('{"title":"Displays","description":"","frontmatter":{},"headers":[],"relativePath":"use/displays.md","filePath":"use/displays.md","lastUpdated":1727214991000}'),o={name:"use/displays.md"};function i(p,e,l,d,r,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="displays" tabindex="-1">Displays <a class="header-anchor" href="#displays" aria-label="Permalink to &quot;Displays&quot;">​</a></h1><h2 id="ssd1306-display-heltec-sx127x-lilygo®-lora32-boards-generic-ssd1306-displays" tabindex="-1">SSD1306 Display (Heltec SX127X, LILYGO® LoRa32 boards, generic SSD1306 displays) <a class="header-anchor" href="#ssd1306-display-heltec-sx127x-lilygo®-lora32-boards-generic-ssd1306-displays" aria-label="Permalink to &quot;SSD1306 Display (Heltec SX127X, LILYGO® LoRa32 boards, generic SSD1306 displays)&quot;">​</a></h2><p>Several options are available for the display of information on the SSD1306 display. Some options are exclusive to each other, and when a different option is enabled, the current option is disabled.</p><p>The current SSD1306 display states are being published to the <code>SSD1306toMQTT</code> topic, e.g.</p><p><code>{&quot;onstate&quot;:true,&quot;brightness&quot;:50,&quot;display-flip&quot;:true,&quot;idlelogo&quot;:true,&quot;log-oled&quot;:false,&quot;json-oled&quot;:true}</code></p><h3 id="display-on-off" tabindex="-1">Display ON/OFF <a class="header-anchor" href="#display-on-off" aria-label="Permalink to &quot;Display ON/OFF&quot;">​</a></h3><p>To turn the SSD1306 display on or off.</p><p>This can be enabled with the compiler directive <code>-DDISPLAY_STATE=true</code>.</p><p>MQTT Display OFF command:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m {&quot;onstate&quot;:false}</code></p><p>MQTT Display ON command:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m {&quot;onstate&quot;:true}</code></p><h4 id="usage-of-a-touch-gpio-display-blanking" tabindex="-1">Usage of a touch GPIO display blanking <a class="header-anchor" href="#usage-of-a-touch-gpio-display-blanking" aria-label="Permalink to &quot;Usage of a touch GPIO display blanking&quot;">​</a></h4><p>Support can be enabled to use a GPIO pin as a simple touch sensor to enable the display. When enabled, the display will blank after 30 seconds, and when GPIO 2 is touched, the display will enable for 30 seconds. For testing a wire was connected to the GPIO pin.</p><p>This can be enabled with the compiler directive <code>-DDISPLAY_BLANKING=true</code></p><p>Blanking Compiler Directives</p><table tabindex="0"><thead><tr><th>Directive</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>DISPLAY_BLANKING</td><td>false</td><td>Enables touch based display blanking</td></tr><tr><td>DISPLAY_BLANKING_TOUCH_GPIO</td><td>2</td><td>GPIO pin to use the touch. Must be a touch supported GPIO pin</td></tr><tr><td>DISPLAY_BLANKING_START</td><td>30</td><td>Seconds to wait before disabling the display</td></tr></tbody></table><h3 id="brightness" tabindex="-1">Brightness <a class="header-anchor" href="#brightness" aria-label="Permalink to &quot;Brightness&quot;">​</a></h3><p>The display brightness can be set between 0-100%.</p><p>It is recommended to set a value lower than 100 to extend the life of the OLED display. The default setting is 50.</p><p>This can be set with the compiler directive <code>-DDISPLAY_BRIGHTNESS=50</code>.</p><p>or with the runtime command</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m {&quot;brightness&quot;:50}</code></p><h3 id="metric-or-imperial-property-units" tabindex="-1">Metric or Imperial property units <a class="header-anchor" href="#metric-or-imperial-property-units" aria-label="Permalink to &quot;Metric or Imperial property units&quot;">​</a></h3><p>To have applicable device properties displayed in Imperial units, e.g. °F for temperature.</p><p>This can be set with the compiler directive <code>-DDISPLAY_METRIC=false</code>.</p><p>As the display Metric setting is being defined in the WebUI part of OpenMQTTGateway changes need to be sent there with the runtime command</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoWebUI/config -m {&quot;displayMetric&quot;:false}</code></p><h3 id="rotating-the-display-by-180-degrees" tabindex="-1">Rotating the display by 180 degrees <a class="header-anchor" href="#rotating-the-display-by-180-degrees" aria-label="Permalink to &quot;Rotating the display by 180 degrees&quot;">​</a></h3><p>This can be set with the compiler directive <code>-DDISPLAY_FLIP=false</code>.</p><p>or with the runtime command</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m {&quot;display-flip&quot;:false}</code></p><h3 id="display-idle-logo" tabindex="-1">Display idle Logo <a class="header-anchor" href="#display-idle-logo" aria-label="Permalink to &quot;Display idle Logo&quot;">​</a></h3><p>To display the OpenMQTTGateway logo during device display idle time. This reduces the likelihood of burn-in.</p><p>This can be set with the compiler directive <code>-DDISPLAY_IDLE_LOGO=true</code>.</p><p>or at runtime with</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m {&quot;idlelogo&quot;:true}</code></p><h3 id="setting-the-log-output" tabindex="-1">Setting the log output <a class="header-anchor" href="#setting-the-log-output" aria-label="Permalink to &quot;Setting the log output&quot;">​</a></h3><p>The display of serial log messages to the display can be enabled via compiler directive <code>-DLOG_TO_OLED=true</code> or via MQTT commands.</p><p>For example if you want to set the serial log to OLED</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m &#39;{&quot;log-oled&quot;:true}&#39;</code></p><p>you can also revert it back with</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m &#39;{&quot;log-oled&quot;:false}&#39;</code></p><p>The log level of the messages displayed is Errors and Warnings, and this can only be changed via the compiler directive <code>-DLOG_LEVEL_OLED=LOG_LEVEL_NOTICE</code>.</p><h3 id="displaying-module-json-messages-default" tabindex="-1">Displaying Module json messages (default) <a class="header-anchor" href="#displaying-module-json-messages-default" aria-label="Permalink to &quot;Displaying Module json messages (default)&quot;">​</a></h3><p>The display of messages from various modules is also supported. Currently supported modules include <code>ZgatewayRTL_433</code>, <code>ZgatewayBT</code> and <code>ZsensorBME280</code>.</p><p>This can be enabled with the compiler directive <code>-DJSON_TO_OLED=true</code>.</p><p>You can also change it by MQTT. For example if you want to display module json messages:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m &#39;{&quot;json-oled&quot;:true}&#39;</code></p><p>And to disable the display of module json messages:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m &#39;{&quot;display-json&quot;:false}&#39;</code></p><h3 id="store-the-current-display-configuration-in-the-gateway" tabindex="-1">Store the current display configuration in the gateway <a class="header-anchor" href="#store-the-current-display-configuration-in-the-gateway" aria-label="Permalink to &quot;Store the current display configuration in the gateway&quot;">​</a></h3><p>To store the running display configuration into non-volatile storage on the gateway use the following command. This assures persistence across restarts.</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m &#39;{&quot;save&quot;:true}&#39;</code></p><p>At any time, you can reload the stored configuration with the command:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m &#39;{&quot;load&quot;:true}&#39;</code></p><p>If you want to erase the stored configuration, use the command:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m &#39;{&quot;erase&quot;:true}&#39;</code></p><p>Note that this will not change the running configuration, it only ensures that the default configuration is used at next startup.</p><p>If you want to load the default configuration use the command:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoSSD1306/config -m &#39;{&quot;init&quot;:true}&#39;</code></p><p>Note that this will not change the stored configuration, <code>erase</code> or <code>save</code> is still needed to overwrite the saved configuration.</p><h3 id="connecting-a-generic-ssd1306-display-to-esp32" tabindex="-1">Connecting a generic SSD1306 display to ESP32 <a class="header-anchor" href="#connecting-a-generic-ssd1306-display-to-esp32" aria-label="Permalink to &quot;Connecting a generic SSD1306 display to ESP32&quot;">​</a></h3><p>It is possible to connect a generic SSD1306 display with resolution 128*64 to the hardware setups. This example describes how to do it with the ESP32 board.</p><ul><li>Connect the display to the ESP32 (display → ESP32): <ul><li>VCC → 5V (or 3.3V, check your display documentation)</li><li>GND → GND</li><li>SCL → pin 22</li><li>SDA → pin 21</li></ul></li><li>Modify the environment definition in <code>environments.ini</code>. <ul><li>Add the display library:<div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lib_deps =</span></span>
<span class="line"><span>  \${com-esp32.lib_deps}</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>  \${libraries.ssd1306}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div></li><li>Add relevant build flags:<div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>build_flags =</span></span>
<span class="line"><span>  \${com-esp32.build_flags}</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>; *** Generic SSD1306 OLED Options **</span></span>
<span class="line"><span>  &#39;-DZdisplaySSD1306=&quot;GenericSSD1306&quot;&#39;</span></span>
<span class="line"><span>  &#39;-DOLED_SDA=21&#39;               ; SSD1306 pin SDA</span></span>
<span class="line"><span>  &#39;-DOLED_SCL=22&#39;               ; SSD1306 pin SCL</span></span>
<span class="line"><span>  &#39;-DGenericSSD1306=true&#39;</span></span>
<span class="line"><span>  &#39;-DJSON_TO_OLED=true&#39;</span></span>
<span class="line"><span>  &#39;-DDISPLAY_PAGE_INTERVAL=30&#39;</span></span>
<span class="line"><span>;  &#39;-DLOG_TO_OLED=true&#39;         ; Enable log to OLED</span></span>
<span class="line"><span>;  &#39;-DLOG_LEVEL_OLED=LOG_LEVEL_NOTICE&#39;</span></span>
<span class="line"><span>;  &#39;-DDISPLAY_IDLE_LOGO=false&#39;</span></span>
<span class="line"><span>;  &#39;-DDISPLAY_BRIGHTNESS=80&#39;</span></span>
<span class="line"><span>;  &#39;-DDISPLAY_METRIC=false&#39;</span></span>
<span class="line"><span>;  &#39;-DDISPLAY_FLIP=false&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div></li></ul></li></ul>`,65)])])}const m=a(o,[["render",i]]);export{h as __pageData,m as default};
